// Exact acknowledged owned fixtures only. No provisioning, registration, grant or mutation endpoints.
import fs from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';
const inputPath=process.argv[2];if(!inputPath)throw Error('Missing private current INPUTS_ACK manifest; no requests sent');
const input=JSON.parse(await fs.readFile(inputPath,'utf8'));
const refs={PROD:'YOUR_PROJECT_REF',DEV:'YOUR_PROJECT_REF'};
const roots={data_source:'workspace_data_sources',data_source_schedule:'data_source_schedules',db_connection:'rekon_db_connections',inline_api_source:'rekon_inline_api_sources',erp_connection:'erp_connector_configs',file_watcher:'data_watchers',aidp_template:'aidp_templates',aidp_document:'aidp_documents',data_prep_pipeline:'data_prep_pipelines',reconciliation:'recon_definitions'};
const uuid=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(x);
if(input.ack!=='CURRENT_OWNED_SYNTHETIC_MAPPING_READONLY'||!refs[input.environment]||!uuid(input.tenantId)||!input.resources?.length||input.resources.some(r=>!roots[r.type]||!uuid(r.id)||!Array.isArray(r.expectedBusinessUnits)||!Array.isArray(r.expectedGroups)||!Array.isArray(r.expectedGrantIds)||!Array.isArray(r.expectedAuditIds)))throw Error('Incomplete exact current owned-input ACK; no requests sent');
const transport=JSON.parse(await fs.readFile(input.transportFile,'utf8'));
if(transport.projectRef!==refs[input.environment]||new URL(transport.apiUrl).hostname!==refs[input.environment]+'.supabase.co'||transport.anonKey.startsWith('sb_secret_'))throw Error('Wrong public environment transport; no requests sent');
const output=path.resolve('scripts/qa/output/resource-mapping-display-20261004','readonly-'+new Date().toISOString().replace(/[:.]/g,'-'));await fs.mkdir(output);
const result={at:new Date().toISOString(),environment:input.environment,tenant:input.tenantId,status:'INCOMPLETE',checks:[],mutationCount:0,resources:[],limitations:'RPC metadata is not root/action authorization. Root RLS read and grant/audit records are checked separately. No grant changes or approval claims.'};
const hash=x=>createHash('sha256').update(JSON.stringify(x)).digest('hex');
const same=(a,b)=>hash([...a].sort())===hash([...b].sort());
const check=(label,pass)=>{result.checks.push({label,pass});if(!pass)throw Error('Qualified readback failed: '+label);};
async function actor(spec){const s=JSON.parse(await fs.readFile(spec.sessionFile,'utf8')),claims=JSON.parse(Buffer.from(s.access_token.split('.')[1],'base64url'));if(claims.sub!==spec.id||claims.aal!=='aal2'||claims.exp*1000<Date.now()+30000)throw Error('Fresh real owned MFA session required; no automatic shared refresh writes');const headers={apikey:transport.anonKey,Authorization:'Bearer '+s.access_token,'Content-Type':'application/json'};const r=await fetch(transport.apiUrl+'/auth/v1/user',{headers,signal:AbortSignal.timeout(20000)});if(!r.ok||(await r.json()).id!==spec.id)throw Error('Actual provider identity readback failed');const a={id:spec.id,headers};const member=await get(a,'tenant_members',{select:'user_id,role,active',tenant_id:'eq.'+input.tenantId,user_id:'eq.'+spec.id});check('current '+spec.kind+' identity/MFA/tenant role',member.http===200&&member.rows.length===1&&member.rows[0].active&&member.rows[0].role===spec.role);return a;}
async function get(a,table,query){const r=await fetch(transport.apiUrl+'/rest/v1/'+table+'?'+new URLSearchParams(query),{headers:a.headers,signal:AbortSignal.timeout(20000)});return {http:r.status,rows:await r.json()};}
async function summary(a,type,ids){const r=await fetch(transport.apiUrl+'/rest/v1/rpc/get_data_resource_access_summary',{method:'POST',headers:a.headers,body:JSON.stringify({_resource_type:type,_resource_ids:ids}),signal:AbortSignal.timeout(20000)});return {http:r.status,rows:await r.json()};}
async function currentPermissions(a){const r=await fetch(transport.apiUrl+'/rest/v1/rpc/effective_user_permissions',{method:'POST',headers:a.headers,body:JSON.stringify({_user_id:a.id,_tenant_id:input.tenantId}),signal:AbortSignal.timeout(20000)});return {http:r.status,rows:await r.json()};}
try{
  if(input.admin?.role!=='tenant_admin'||input.viewer?.role==='tenant_admin'||input.admin?.id===input.viewer?.id)throw Error('Distinct actual admin and ordinary viewer inputs required');
  const admin=await actor({...input.admin,kind:'admin'}),viewer=await actor({...input.viewer,kind:'ordinary viewer'});
  const permissions=await currentPermissions(viewer);check('current ordinary effective permissions read independently of mapping names',permissions.http===200&&Array.isArray(permissions.rows));result.currentViewerPermissions=[...new Set(permissions.rows.map(r=>r.permission_id))].sort();
  if(input.viewer.expectedPermissionIds)check('exact acknowledged current viewer permissions',same(result.currentViewerPermissions,input.viewer.expectedPermissionIds));
  for(const resource of input.resources){
    const owner=await get(admin,roots[resource.type],{select:'id,tenant_id',id:'eq.'+resource.id,tenant_id:'eq.'+input.tenantId});check(resource.type+' exact owned tenant root',owner.http===200&&owner.rows.length===1);
    const root=await get(viewer,roots[resource.type],{select:'id,tenant_id',id:'eq.'+resource.id,tenant_id:'eq.'+input.tenantId});check(resource.type+' actual ordinary root RLS outcome',root.http===200&&root.rows.length===(resource.expectedReadable?1:0));
    const meta=await summary(viewer,resource.type,[resource.id]);check(resource.type+' current exact summary outcome',meta.http===200&&meta.rows.length===(resource.expectedSummaryVisible?1:0));
    if(resource.expectedSummaryVisible){const row=meta.rows[0];check(resource.type+' actual BU/group names and counts',row.resource_id===resource.id&&row.resource_type===resource.type&&same(row.business_unit_names,resource.expectedBusinessUnits)&&same(row.user_group_names,resource.expectedGroups)&&row.business_unit_count===resource.expectedBusinessUnits.length&&row.user_group_count===resource.expectedGroups.length);}
    const adminMeta=await summary(admin,resource.type,[resource.id]);check(resource.type+' actual admin summary exists',adminMeta.http===200&&adminMeta.rows.length===1);
    // Audits and grants are exact admin readback, separate from ordinary metadata and root RLS.
    if(resource.type==='data_source'&&resource.uploadIds){const uploads=await get(viewer,'workspace_data_source_uploads',{select:'id,data_source_id,tenant_id',data_source_id:'eq.'+resource.id,tenant_id:'eq.'+input.tenantId});check('FILE exact acknowledged uploaded children under current RLS',uploads.http===200&&same(uploads.rows.map(x=>x.id),resource.uploadIds));}
    const registry=resource.registryId;
    let grants=[],audits=[];
    if(registry){if(!uuid(registry))throw Error('Invalid exact registry input');const registryRow=await get(admin,'data_resource_registry',{select:'id,resource_type,'+resource.type+'_id',id:'eq.'+registry,tenant_id:'eq.'+input.tenantId});check(resource.type+' exact registry/root association',registryRow.http===200&&registryRow.rows.length===1&&registryRow.rows[0].resource_type===resource.type&&registryRow.rows[0][resource.type+'_id']===resource.id);const g=await get(admin,'data_resource_registry_grants',{select:'id,action,bu_id,principal_type,principal_group_id,principal_user_id',registry_id:'eq.'+registry,tenant_id:'eq.'+input.tenantId});check(resource.type+' exact current grant IDs',g.http===200&&same(g.rows.map(x=>x.id),resource.expectedGrantIds));grants=g.rows;const a=await get(admin,'data_resource_registry_admin_audit',{select:'id,actor_id,operation',registry_id:'eq.'+registry,tenant_id:'eq.'+input.tenantId,limit:'100'});check(resource.type+' acknowledged audit IDs retained',a.http===200&&resource.expectedAuditIds.every(id=>a.rows.some(x=>String(x.id)===String(id))));audits=a.rows;}
    else if(resource.type==='reconciliation'){const g=await get(admin,'recon_definition_bu_grants',{select:'id,action,bu_id,principal_type,principal_id',recon_id:'eq.'+resource.id,tenant_id:'eq.'+input.tenantId});check('reconciliation exact current grants',g.http===200&&same(g.rows.map(x=>x.id),resource.expectedGrantIds));grants=g.rows;const a=await get(admin,'audit_log',{select:'id,actor_user_id,action',resource_id:'eq.'+resource.id,tenant_id:'eq.'+input.tenantId,limit:'100'});check('reconciliation acknowledged audit IDs retained',a.http===200&&resource.expectedAuditIds.every(id=>a.rows.some(x=>String(x.id)===String(id))));audits=a.rows;}
    else throw Error('Exact current owned registry ID prerequisite missing');
    result.resources.push({type:resource.type,id:resource.id,ordinaryMetadata:meta,actualRootReadable:root.rows.length===1,adminMetadata:adminMeta,grantProjectionSHA256:hash(grants),auditProjectionSHA256:hash(audits),grantCount:grants.length,auditCount:audits.length});
  }
  result.status='ACTUAL_CURRENT_OWNED_MAPPING_READONLY_PASS';
}catch(e){result.error=String(e.message).split('\n')[0];process.exitCode=1;}
await fs.writeFile(path.join(output,'RESULT.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({status:result.status,checks:result.checks.length,result:path.join(output,'RESULT.json'),error:result.error??null,mutationCount:0}));
